    /** step nbest: would the page or the bubble act on this sentence (a whole phrase, or a command prefix with words after it) */
    fun known(t: String): Boolean { val n = norm(t); if (n.isEmpty()) return false; if (n in KNOWN_EXACT) return true; return KNOWN_PREFIX.any { n == it || n.startsWith("$it ") } }
